// Default Assignment: Member-wise Copy (Rule of Zero)

class Payload {
    int size = 0;
    double cost = 0.0;
};

// Compiler-Generated Signature:
// Payload& operator=(const Payload& other);

Payload p1;
Payload p2 = {5, 100.5};

p1 = p2; 
// p1.size is assigned p2.size (5)
// p1.cost is assigned p2.cost (100.5)

// Note: This default operator results in 
// a shallow copy if raw pointers are present.
